'Yankee Stadium'),('Yokohama Country Club'),('Yulman Stadium'),('Zoeller Field at Dix Stadium'),('bet365 Stadium'),('crypto.com Arena'),('loanDepot park'),('Şükrü Saracoğlu Stadium')) SELECT venue, COUNT(*) AS games, MIN(created_at) AS first_created, MAX(date) AS last, group_concat(DISTINCT sport) AS sports, group_concat(DISTINCT home) AS homes FROM (SELECT venue, sport, home, date, created_at FROM regular_season_games UNION ALL SELECT venue, sport, home, date, created_at FROM postseason_games) WHERE date >= '2026-07-01' AND sport NOT IN ('NBA','NHL') AND venue IS NOT NULL AND venue <> '' AND venue NOT IN (SELECT v FROM known) GROUP BY venue ORDER BY venue